import sys
from bisect import bisect_left

def main():
    data = sys.stdin.read().split()
    n, k = int(data[0]), int(data[1])
    a = sorted(int(x) for x in data[2:2 + n])
    best = None
    for i in range(n - 1):
        j = bisect_left(a, a[i] + k, i + 1)
        for c in (j - 1, j):
            if i + 1 <= c < n:
                cand = (abs(a[c] - a[i] - k), a[i] + a[c])
                if best is None or cand < best:
                    best = cand
    print(best[1])

main()

